+# mobile-app
+
+This module contains a function to identify whether requests are coming from the WordPress mobile apps.
+
+### Usage
+
+Simple usage:
+
+```js
+import { isWpMobileApp } from 'lib/mobile-app';
+
+if ( isWpMobileApp() ) {
+	// Perform a mobile app-specific logic.
+}
+```
\ No newline at end of file
diff --git a/client/lib/mobile-app/index.js b/client/lib/mobile-app/index.js
new file mode 100644
index 0000000000000..6e368cb5ccd28
--- /dev/null
+++ b/client/lib/mobile-app/index.js
@@ -0,0 +1,10 @@
+/** @format **/
+
+/**
+ * Returns whether user is using a WordPress mobile app.
+ *
+ * @returns {Boolean} Whether the user agent matches the ones used on the WordPress mobile apps.
+ */
+export function isWpMobileApp() {
+	return navigator && /wp-(android|iphone)/.test( navigator.userAgent );
+}

